; can_2a.asm -- CAN 2.0A node on the frozen ISA (issue #450, catalog
; #443): transmit a standard data frame with bitwise arbitration,
; receive one with de-stuffing, CRC check and ACK drive. GENERATED by
; firmware/tools/gen_can_2a.py -- do not edit the literals by hand;
; regenerate and re-assemble. See firmware/README.md for the program
; note and the acceptance criteria this image is evidence for.
;
; Frame transmitted: ID 0x5A5, RTR=0 (data frame), DLC 3,
; data 0x11 0x1F 0x22; 43 unstuffed bits
; SOF..data, 2 stuff bits on the wire, CRC-15 poly 0x4599 seed 0
; (DR 0015 P1, one CRC_BIT per destuffed bit; stuffing by the P2 LINE
; unit, equal-bits rule N=5, NRZ off). Status words on uo_out keep bit 0
; recessive: 0x41/0x61 after the transmit (ACK seen / not), 0xC1/0xC3/0xC5
; at HALT (received ok / CRC error / stuff error).
;
; Timing: exactly 400 core cycles per bit, sample point at offset 300
; (75%). Every path through a bit window is padded to the
; same OUT-to-OUT span; the generator derives each WAIT from the path's
; instruction count (DR 0001: 1 cycle per instruction except WAIT imm8 =
; imm8+1 and the RCTL PM_DATA_HI read = 2).
setup:
	LDI   R3, 0x01
	OUT   UO_OUT, R3
	LDI   R1, 0x0E
	WCTL  CRC_CFG, R1
	LDI   R1, 0x99
	WCTL  CRC_POLY, R1
	LDI   R1, 0x45
	WCTL  CRC_POLY, R1
	LDI   R1, 0x0E
	WCTL  CRC_CFG, R1
	XOR   R2, R2
	WCTL  CRC_STATE, R2
	WCTL  CRC_STATE, R2
	LDI   R1, 0xD8
	WCTL  LINE_CFG, R1
	LDI   R1, 0xF8
	WCTL  PM_ADDR, R1
	LDI   R2, 0x05
	WCTL  UIO_DIR, R2
	RCTL  R1, PM_DATA_HI
	RCTL  R0, PM_DATA_LO
	LDI   R2, 0x08
	WAIT  255	; bus idle before this node's SOF

; ---- the transmit loop: every bit of SOF..last data byte goes
; ---- through this body (arbitrated, stuffed, CRC-fed). The byte
; ---- boundary dispatch walks UIO_DIR: 5..2 = table bytes left,
; ---- 1 = load the 3-bit tail, 0 = tail done -> the CRC readout.
	.cyclesec can_tx_bit
tx_bit:
	WCTL  LINE_PUT, R0
	RCTL  R1, LINE_OUT
	OUT   UO_OUT, R1
	AND   R1, R3
	BZ    tx_dom
	WAIT  255	; to the sample point
	WAIT  40 
	IN    R1, UI_IN
	AND   R1, R3
	BZ    arb_lost
tx_join:
	RCTL  R1, LINE_STUF
	AND   R1, R3
	BNZ   tx_stuff
	WCTL  CRC_BIT, R0
	SHF   R0, RIGHT
	SUB   R2, R3
	BZ    tx_bnd
	WAIT  86 	; rest of the bit
	JMP   tx_bit
	.endcyclesec
tx_dom:
	WAIT  255	; dominant bit: arbitration cannot be lost
	WAIT  42 
	JMP   tx_join
tx_stuff:
	WAIT  90 	; stuff slot pad
	JMP   tx_bit
tx_bnd:
	RCTL  R1, UIO_DIR
	OR    R1, R1
	BZ    tx_crcout
	SUB   R1, R3
	BZ    tx_tail
	WCTL  UIO_DIR, R1
	RCTL  R1, PM_DATA_HI
	RCTL  R0, PM_DATA_LO
	LDI   R2, 0x08
	WAIT  76 	; byte-boundary pad
	JMP   tx_bit
tx_tail:
	WCTL  UIO_DIR, R1
	LDI   R0, 0x02
	LDI   R2, 0x03
	WAIT  78 	; tail-load pad
	JMP   tx_bit

; ---- the CRC readout: rewind, read the two state bytes, stash byte
; ---- 0 in PM_ADDR (the table pointer is spent), reverse byte 1 (the
; ---- top seven bits, state[14] first on the wire) and send it;
; ---- byte 0 follows through the tx_cb1bnd reload.
tx_crcout:
	LDI   R1, 0x0E
	WCTL  CRC_CFG, R1
	RCTL  R0, CRC_NEXT
	WCTL  PM_ADDR, R0
	RCTL  R0, CRC_NEXT
	SHF   R0, LEFT
	XOR   R1, R1
rev8a:
	MOV   R2, R0
	AND   R2, R3
	ADD   R1, R1
	OR    R1, R2
	SHF   R0, RIGHT
	OR    R0, R0
	BNZ   rev8a
	MOV   R0, R1
	LDI   R2, 0x07
	WAIT  18 	; CRC byte 1 pad
	JMP   tx_cbit1
	.cyclesec can_tx_crc1
tx_cbit1:
	WCTL  LINE_PUT, R0
	RCTL  R1, LINE_OUT
	OUT   UO_OUT, R1
	RCTL  R1, LINE_STUF
	AND   R1, R3
	BNZ   tx_cs1
	SHF   R0, RIGHT
	SUB   R2, R3
	BZ    tx_cb1bnd
	WAIT  255	; rest of the bit
	WAIT  133
	JMP   tx_cbit1
	.endcyclesec
tx_cs1:
	WAIT  255	; stuff slot pad
	WAIT  136
	JMP   tx_cbit1
tx_cb1bnd:
	RCTL  R0, PM_ADDR
	XOR   R1, R1
rev8b:
	MOV   R2, R0
	AND   R2, R3
	ADD   R1, R1
	OR    R1, R2
	SHF   R0, RIGHT
	OR    R0, R0
	BNZ   rev8b
	MOV   R0, R1
	LDI   R2, 0x08
	WAIT  255	; CRC byte 0 pad
	WAIT  73 
	JMP   tx_cbit0
	.cyclesec can_tx_crc0
tx_cbit0:
	WCTL  LINE_PUT, R0
	RCTL  R1, LINE_OUT
	OUT   UO_OUT, R1
	RCTL  R1, LINE_STUF
	AND   R1, R3
	BNZ   tx_cs0
	SHF   R0, RIGHT
	SUB   R2, R3
	BZ    tx_delim
	WAIT  255	; rest of the bit
	WAIT  133
	JMP   tx_cbit0
	.endcyclesec
tx_cs0:
	WAIT  255	; stuff slot pad
	WAIT  136
	JMP   tx_cbit0

; ---- CRC delimiter, ACK slot (sampled at the sample point), ACK
; ---- delimiter, EOF (7) + IFS (3), then the transmit status word.
tx_delim:
	WAIT  255	; the last CRC bit's window
	WAIT  135
	LDI   R1, 0x03
	OUT   UO_OUT, R1
	WAIT  255	; the delimiter + ACK slot, to the ACK sample point
	WAIT  255
	WAIT  186
	IN    R1, UI_IN
	AND   R1, R3
	XOR   R1, R3
	WCTL  UIO_DIR, R1
	WAIT  95 	; rest of the ACK slot
	OUT   UO_OUT, R3
	WAIT  255	; the ACK delimiter bit
	WAIT  141
	LDI   R2, 0x0A
tx_eif:
	WAIT  255	; one recessive bit
	WAIT  141
	SUB   R2, R3
	BNZ   tx_eif
	RCTL  R1, UIO_DIR
	OR    R1, R1
	BZ    tx_noack
	LDI   R1, 0x41
	JMP   tx_status
tx_noack:
	LDI   R1, 0x61
tx_status:
	OUT   UO_OUT, R1
	JMP   rx_setup

; ---- arbitration lost: drive recessive, wait out the winner's frame
; ---- (20 recessive bit times: the winner's trailing CRC run (up to
; ---- 6, stuffing-capped) + delimiter + ACK + delimiter + EOF + IFS + margin).
arb_lost:
	OUT   UO_OUT, R3
arb_again:
	LDI   R2, 0x14
arb_wait:
	WAIT  255	; one idle bit
	WAIT  138
	IN    R1, UI_IN
	AND   R1, R3
	BZ    arb_again
	SUB   R2, R3
	BNZ   arb_wait
	JMP   setup

; ---- receive: reseed the engines, poll for the SOF falling edge
; ---- (the poll period is ~11 cycles, so the hard sync lands within
; ---- ~11 cycles of the edge; DR 0021's async-input caveat is handled
; ---- by the bench driving CAN_RXD synchronously to the core clock).
rx_setup:
	LDI   R1, 0x0E
	WCTL  CRC_CFG, R1
	XOR   R2, R2
	WCTL  CRC_STATE, R2
	WCTL  CRC_STATE, R2
	LDI   R1, 0xD8
	WCTL  LINE_CFG, R1
rx_sof:
	IN    R1, UI_IN
	AND   R1, R3
	BZ    rx_sync
	WAIT  6
	JMP   rx_sof
rx_sync:
	WCTL  CRC_BIT, R1
	WCTL  LINE_PUT, R1
	LDI   R0, 0x39
	WAIT  255	; to the first sample point
	WAIT  44 
	JMP   rx_bit

; ---- the receive loop: sample at the sample point, verify every slot
; ---- against the LINE unit's own prediction (a mismatch is a stuff
; ---- error), de-stuff, feed the CRC, count down the 58 destuffed
; ---- bits of a DLC-3 frame (the register ceiling's scope cut).
	.cyclesec can_rx_bit
rx_bit:
	WAIT  255	; to the next sample point
	WAIT  131
	IN    R1, UI_IN
	AND   R1, R3
	WCTL  LINE_PUT, R1
	RCTL  R2, LINE_OUT
	XOR   R2, R1
	AND   R2, R3
	BNZ   rx_err
	RCTL  R2, LINE_STUF
	AND   R2, R3
	BNZ   rx_skip
	WCTL  CRC_BIT, R1
	SUB   R0, R3
	BNZ   rx_bit
	.endcyclesec
rx_check:
	LDI   R2, 0x0E
	WCTL  CRC_CFG, R2
	RCTL  R1, CRC_NEXT
	WCTL  UIO_DIR, R1
	RCTL  R1, CRC_NEXT
	RCTL  R2, UIO_DIR
	OR    R1, R2
	WAIT  78 	; to the CRC delimiter boundary
	LDI   R1, 0x03
	OUT   UO_OUT, R1
	WAIT  255	; the delimiter bit
	WAIT  137
	BZ    rx_ack
rx_noack:
	XOR   R2, R2
	WCTL  UIO_DIR, R2
	LDI   R1, 0x03
	OUT   UO_OUT, R1
	JMP   rx_ackdel
rx_ack:
	LDI   R2, 0x01
	WCTL  UIO_DIR, R2
	LDI   R1, 0x00
	OUT   UO_OUT, R1
	JMP   rx_ackdel
rx_ackdel:
	WAIT  255	; rest of the ACK slot
	WAIT  140
	OUT   UO_OUT, R3
	WAIT  255	; the ACK delimiter bit
	WAIT  141
	LDI   R2, 0x0A
rx_eif:
	WAIT  255	; one recessive bit
	WAIT  141
	SUB   R2, R3
	BNZ   rx_eif
	RCTL  R1, UIO_DIR
	OR    R1, R1
	BZ    rx_st3
	LDI   R1, 0xC1
	JMP   rx_fin
rx_st3:
	LDI   R1, 0xC3
rx_fin:
	OUT   UO_OUT, R1
	HALT
rx_skip:
	WAIT  0  	; stuff slot pad
	JMP   rx_bit

; ---- stuff error: abandon the frame, drive no ACK, report.
rx_err:
	OUT   UO_OUT, R3
	LDI   R2, 0x0C
rx_errw:
	WAIT  255	; one recessive bit
	WAIT  141
	SUB   R2, R3
	BNZ   rx_errw
	LDI   R1, 0xC5
	OUT   UO_OUT, R1
	HALT

; ---- the transmit table: five bit-reversed bytes (stream bits 0..39,
; ---- MSB-first packed then bit-reversed so SHF RIGHT presents the
; ---- earliest bit from bit 0). Each is a WAIT word: never executed,
; ---- only read as data through PM_DATA_HI + PM_DATA_LO (DR 0012).
tx_table:
	WAIT  0x5A
	WAIT  0x0A
	WAIT  0x46
	WAIT  0xC4
	WAIT  0x27
